"""Build a portable offline classroom presentation from verified local outputs."""
import base64
import csv
import html
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
rows = list(csv.DictReader((ROOT / 'data/patches/index.csv').open(newline='')))
counts = Counter(r['split'] for r in rows)

def photo(name, caption):
    data = base64.b64encode((ROOT / 'docs/img' / name).read_bytes()).decode()
    return f'<figure><img src="data:image/png;base64,{data}" alt="{html.escape(caption)}"><figcaption>{caption}</figcaption></figure>'

